arguments.command:
cat << 'EOF' > /tmp/stackalloc_nint.cs
using System;

Span<nint> span = stackalloc nint[5];
for (int i = 0; i < span.Length; i++)
    span[i] = (nint)(i * 10);

foreach (var val in span)
    Console.WriteLine(val);

Console.WriteLine($"nint size: {nint.Size} bytes");
EOF
dotnet-script /tmp/stackalloc_nint.cs 2>&1 || dotnet run --project /tmp/stackalloc_nint.cs 2>&1 || (cd /tmp && dotnet new console -o stackalloc_test --force -n StackallocTest && cp stackalloc_nint.cs stackalloc_test/Program.cs && dotnet run --project stackalloc_test)

